import hashlib,json
checks=[]
for obj in raw['objects']:
 vertices=np.asarray(obj['vertices'],dtype=float); tris=np.asarray(obj['triangles'],dtype=int); xyz=vertices[tris]
 normals=np.cross(xyz[:,1]-xyz[:,0],xyz[:,2]-xyz[:,0]); normals/=np.linalg.norm(normals,axis=1)[:,None]
 groups={}
 for idx,normal in enumerate(normals):
  key=tuple(normal.tolist())+(float(np.dot(normal,xyz[idx,0])),)
  groups.setdefault(key,[]).append(idx)
 details=[]
 for key,indices in groups.items():
  edgeowners={}; adjacency={idx:set() for idx in indices}
  for idx in indices:
   tri=tris[idx]
   for first,second in [(tri[0],tri[1]),(tri[1],tri[2]),(tri[2],tri[0])]:
    edge=tuple(sorted([int(first),int(second)]))
    for other in edgeowners.get(edge,[]): adjacency[idx].add(other);adjacency[other].add(idx)
    edgeowners.setdefault(edge,[]).append(idx)
  unseen=set(indices); components=[]
  while unseen:
   stack=[unseen.pop()]; component=[]
   while stack:
    current=stack.pop();component.append(current)
    neighbors=adjacency[current]&unseen;unseen-=neighbors;stack.extend(neighbors)
   components.append(component)
  for component in components:
   points=xyz[component].reshape(-1,3)
   details.append({'triangle_min':min(component),'triangle_max':max(component),'count':len(component),'normal':key[:3],'bounds':[points.min(axis=0).tolist(),points.max(axis=0).tolist()]})
 checks.append({'name':obj['name'],'object_id':obj['object_id'],'instance_id':obj['instance_id'],'vertex_count':len(vertices),'triangle_count':len(tris),'bounds':[vertices.min(axis=0).tolist(),vertices.max(axis=0).tolist()],'maximal_edge_connected_planar_components':details,'geometry_sha256':hashlib.sha256(json.dumps({'vertices':obj['vertices'],'triangles':obj['triangles']},separators=(',',':')).encode()).hexdigest()})
print('RAW_VERIFICATION',checks)
near=next(o for o in raw['objects'] if o['name']=='M4_Near');far=next(o for o in raw['objects'] if o['name']=='M4_Far_00')
xnear=near['vertices'][0][0];distance=1-xnear
print('WHOLE_OBJECT_MEASUREMENT',{'scope':'all 514 Far triangles and all 1 Near triangle','distance_m':distance,'a':[1,0,0],'b':[xnear,0,0],'direction':[-1,0,0],'a_source_triangle':0,'b_source_triangle':0,'proof':'Every Far triangle lies in x>=1; every Near triangle lies in x='+repr(xnear)+'. Thus all point distances >=1-xnear. Both source triangle 0 contain the supplied endpoints, attaining the bound.'})

